 function ensureDraft(){if(draft)return draft;const method=$('method').value,l=layer($('drawLayer').value);if(!l||l.locked)throw Error('Choose an editable destination layer in Advanced');const preferred=$('featureType').value,compatible=method==='polygon'?['parcel','building']:method==='point'?['point']:['boundary','road','footpath','stream','drain','fence','custom-line'];draft={method,geometry:geometry(method),type:compatible.includes(preferred)?preferred:compatible[0],coords:[],vertexMeta:[],layerId:l.id,properties:properties(),snapped:false};return draft}
