 function finish(skipReduce=false){if(!draft?.coords.length)return toast('Tap map points first');const d=draft;if(d.geometry!=='Point'){const problem=G.validate(xy(d.coords),d.geometry==='Polygon');if(problem)return toast(problem)}if(d.method==='line'&&d.coords.length!==2)return toast('Line needs two vertices');if(editingId&&locked(byId(editingId)))return toast('Feature / layer is protected');const dest=layer(d.layerId);if(!dest||dest.locked)return toast('Destination layer is protected or missing');let reduced=null;if(!skipReduce&&d.geometry==='Polygon'&&$('autoReduce').checked&&target()>0&&area(d)>target()+.001)reduced=reduction(d,target());checkpoint();if(reduced){d.coords=reduced.coords;d.vertexMeta=reduced.vertexMeta}const props=properties();props.name ||=((d.geometry==='Polygon'?'Lot ':d.geometry==='Point'?'Point ':'Line ')+(project.features.length+1));props.number=props.name;const f={...copy(d),id:editingId||uid('feature'),properties:props,locked:false,created:byId(editingId)?.created||now(),updated:now()};delete f.method;if(editingId)project.features[project.features.findIndex(x=>x.id===editingId)]=f;else project.features.push(f);selectedId=f.id;draft=null;editingId='';epoch++;stopWalk();mode='select';invalidate();render();save(true);hint('Saved '+props.name+' · '+meta(f)+'. Subdivide or start a new sketch.','SAVED');toast(reduced?'Saved at target extent · shared boundary unchanged':'Joined '+f.geometry+' saved')}
 function snappingFeatures(screen=false){const out=[];if(!project)return out;for(const f of project.features){const l=layer(f.layerId);if(!l?.visible||!l.snap||f.id===editingId||f.type==='annotation')continue;[f.coords,...(f.holes||[])].forEach((c,ring)=>out.push({id:f.id,ring,closed:f.geometry==='Polygon',coords:c.map(p=>screen?screenPoint(ll(p)):toSLD(p))}))}return out}
