 function showSnap(h){snapGroup.clearLayers();if(!h){$('snapStatus').textContent=snapEnabled?'OSNAP ready · '+$('snapMode').selectedOptions[0].text:'OSNAP OFF · free map points';return}const name=snapNames[h.kind];$('snapStatus').textContent=name+' · '+(h.featureId==='__draftstart__'?'Close parcel':byId(h.featureId)?.properties.name||'Reference');L.marker(ll(h.coordinate),{interactive:false,keyboard:false,icon:L.divIcon({className:'',html:'<div class="snap-marker '+h.kind+'">'+(h.kind==='intersection'?'×':'')+'</div>',iconSize:[22,22],iconAnchor:[11,11]})}).addTo(snapGroup).bindTooltip(name,{permanent:true,direction:'top',offset:[0,-12],className:'snap-tooltip'}).openTooltip()}
 function hover(p){if(!project||!['draw','edit','traceStart','traceEnd','insert'].includes(mode)||preview)return;const hit=resolveSnap(p,mode.startsWith('trace'));showSnap(hit);ghostGroup.clearLayers();if(mode==='draw'&&draft?.coords.length&&draft.geometry!=='Point'){const f={...draft,coords:draft.coords.concat([hit?hit.coordinate:coord(p)])};shape(f,ghostGroup,{interactive:false,color:'#bb9137',dashArray:'5,6',weight:2,fillOpacity:.035});updateMeasure(f)}}
 function pickFeature(p){const q=toSLD(coord(p));for(const f of [...project.features].reverse())if(layer(f.layerId)?.visible&&f.geometry==='Polygon'&&G.inside(q,xy(f.coords))&&!(f.holes||[]).some(h=>G.inside(q,xy(h))))return f;const candidates=project.features.filter(f=>layer(f.layerId)?.visible&&f.type!=='annotation').map(f=>({id:f.id,closed:f.geometry==='Polygon',coords:f.coords.map(c=>screenPoint(ll(c)))})),h=G.snap(screenPoint(p),candidates,{radius:28,modes:['endpoint','nearest']});return h?byId(h.featureId):null}
