 function editGeometry(action='edit'){if(!ensure())return;if(!draft){const f=byId(selectedId);if(!f)return toast('Select a feature first');if(locked(f))return toast('Unlock feature / layer first');if(f.holes?.length)return toast('Editing polygons with holes is not supported; original retained');checkpoint();draft={...copy(f),method:methodFor(f),vertexMeta:copy(f.vertexMeta||f.coords.map(()=>({source:'map'})))};editingId=f.id;$('method').value=draft.method;fillProperties(f.properties)}mode=action;renderMap();renderDraft();switchTab('fieldPage');hint(action==='edit'?'Drag a vertex. Area updates during movement. Save changes.':action==='insert'?'Tap an edge to add a vertex.':'Tap a vertex to delete. Undo restores it.','EDIT')}
