 function traceClick(p){const h=resolveSnap(p,true);showSnap(h);if(!h)return toast('Tap closer to a visible reference edge');if(byId(h.featureId).geometry==='Point')return toast('Choose a boundary, not a point');if(mode==='traceStart'){traceStart=h;mode='traceEnd';hint('Shared boundary 2/2: tap its END. All bends are copied.','TRACE');return}if(G.dist(traceStart.point,h.point)<.005)return toast('Choose a different end');const same=h.featureId===traceStart.featureId&&h.ring===traceStart.ring,f=byId(traceStart.featureId);preview={kind:'trace',start:traceStart,end:h,same,alternate:false,closed:f.geometry==='Polygon',coords:traceStart.ring?f.holes[traceStart.ring-1]:f.coords};try{tracePreview()}catch(e){preview=null;previewGroup.clearLayers();throw e}}
