 function showPreview(title,text,accept,swap=false,split=false){$('previewTitle').textContent=title;$('previewText').textContent=text;$('acceptPreview').textContent=accept;$('swapPreviewBtn').classList.toggle('hidden',!swap);$('keepOther').classList.toggle('hidden',!split);$('keepBoth').classList.toggle('hidden',!split);$('previewPanel').classList.remove('hidden')}
 function splitOpen(){if(!ensure())return;if(draft){if(draft.geometry!=='Polygon')return toast('Draw / select a polygon');finish(true);if(draft)return}const f=byId(selectedId);if(!f||f.geometry!=='Polygon')return toast('Select a saved parcel');if(locked(f))return toast('Unlock parcel / layer');if(f.holes?.length)return toast('Subdivision of polygons with holes is not supported. Original retained.');const t=target();if(t<=0||t>=area(f))return toast('Required extent must be positive and smaller than this parcel');$('subdivisionInfo').textContent=(f.properties.name||'Parcel')+' · '+G.arp(area(f))+' → '+G.arp(t);$('subdivisionModal').classList.add('show')}
 function splitStart(kind){const f=byId(selectedId);cut={kind,sourceId:f.id,target:target(),picks:[],side:1};close('subdivisionModal');mode=kind==='parallel'?'splitLine':'splitVertex';switchTab('fieldPage');if(kind==='rotate'){previewGroup.clearLayers();for(const c of f.coords)L.circleMarker(ll(c),{radius:7,color:'#fff',weight:2,fillColor:'#cb922e',fillOpacity:1,interactive:false}).addTo(previewGroup)}hint(kind==='parallel'?'1/3: tap FIRST point of a line across the parcel.':'1/3: tap a highlighted parcel vertex.','SUBDIVIDE')}
