 function splitClick(p){const f=byId(cut.sourceId),q=toSLD(coord(p));if(mode==='splitVertex'){const h=G.snap(screenPoint(p),[{id:f.id,coords:f.coords.map(c=>screenPoint(ll(c))),closed:true}],{modes:['endpoint'],radius:32});if(!h)return toast('Tap a highlighted vertex');cut.picks=[toSLD(f.coords[h.index])];mode='splitLine';hint('2/3: tap second point for line direction.','SUBDIVIDE');return}if(mode==='splitLine'){const h=resolveSnap(p);showSnap(h);const next=h?toSLD(h.coordinate):q;if(cut.picks.length&&G.dist(cut.picks[0],next)<.001)return toast('Choose a different point');cut.picks.push(next);if(cut.picks.length===1){hint('2/3: tap SECOND point across the parcel.','SUBDIVIDE');return}const[a,b]=cut.picks,c=xy(f.coords);if(G.area(G.clip(c,a,b,true))<.001||G.area(G.clip(c,a,b,false))<.001){cut.picks=cut.kind==='rotate'?[a]:[];return toast('Line must cross parcel interior. Pick its direction again.')}drawCutGuide();mode='splitSide';hint('3/3: tap INSIDE the side that needs the required extent.','PICK SIDE');return}if(mode==='splitSide'){if(!G.inside(q,xy(f.coords),false))return toast('Tap inside this parcel');const[a,b]=cut.picks;if(Math.abs(G.cross(a,b,q))/G.dist(a,b)<.03)return toast('Tap clearly on one side');cut.side=G.cross(a,b,q)>0?1:-1;calculatePreview()}}
