 function acceptSplit(which){const v=preview,s=byId(v.sourceId);if(!s||locked(s))return toast('Source parcel protected / missing');checkpoint();const parts=which==='both'?[v.selected,v.other]:[which==='selected'?v.selected:v.other];project.features=project.features.filter(f=>f.id!==s.id);parts.forEach((c,i)=>{const name=which==='both'?(s.properties.name||'Lot')+'-'+(i+1):s.properties.name;const f={...copy(s),id:which==='both'?uid('feature'):s.id,coords:c.map(p=>preserveCoordinate(p,s)),holes:[],labelVisible:true,properties:{...s.properties,name,number:name,parentParcel:s.id},snapped:true,vertexMeta:c.map(()=>({source:'subdivision'})),updated:now()};project.features.push(f);selectedId=f.id});cancelTransient();mode='select';invalidate();render();save(true);hint('Subdivision saved. Undo restores the full original parcel.','SAVED');toast(which==='both'?'Both parcels kept':'Chosen parcel kept; other part removed. Undo can restore it.')}
