 function boundarySelectBegin(){if(!ensure())return;if($('method').value==='point'||$('method').value==='line')return toast('Choose Polygon or Polyline first');ensureDraft();boundaryPicks=[];mode='boundaryPick';preview={kind:'boundarySelection'};close('boundaryModal');showPreview('Select shared boundaries','Tap a saved line / polyline or polygon edge. Tap again to deselect.','Add to sketch');hint('Select adjoining boundaries in order, then Add to sketch.','BOUNDARY')}
