 function acceptBoundaries(){if(!boundaryPicks.length)return toast('Select at least one boundary');const route=G.joinPaths(boundaryPicks.map(x=>xy(x.coords)));preview={kind:'trace',route,start:{featureId:boundaryPicks[0].featureId}};try{acceptTrace()}finally{if(preview)preview={kind:'boundarySelection'}}}
 function scalePreview(){if(draft)return toast('Save sketch first');const f=byId(selectedId);if(!f||f.geometry!=='Polygon'||locked(f))return toast('Select editable polygon');if(f.snapped||layer(f.layerId)?.source!=='survey'||f.holes?.length)return toast('Use Subdivide for imported / shared-boundary parcels');const t=target(),q=xy(f.coords);if(t<=0)throw Error('Enter target area');const c=G.labelPoint(q),k=Math.sqrt(t/G.area(q));preview={kind:'scale',sourceId:f.id,coords:q.map(p=>fromSLD([c[0]+(p[0]-c[0])*k,c[1]+(p[1]-c[1])*k]))};previewGroup.clearLayers();shape({...f,coords:preview.coords},previewGroup,{color:'#dc9c2b',interactive:false});showPreview('Free sketch scale preview','All vertices move. Target '+G.arp(t)+'. Shared boundaries excluded.','Accept scale')}
 function joinPick(id){const f=byId(id);if(f.geometry!=='LineString')return toast('Choose saved boundary lines');joinIds.includes(id)?joinIds.splice(joinIds.indexOf(id),1):joinIds.push(id);renderMap();$('joinStatus').textContent=joinIds.length+' lines selected in order'}
 function joinFinish(){if(!joinIds.length)return toast('Select boundary lines');let c=[];for(const [index,id] of joinIds.entries()){let part=copy(byId(id).coords);if(index===0&&joinIds.length>1){const next=byId(joinIds[1]).coords,ends=[toSLD(next[0]),toSLD(next.at(-1))],first=Math.min(...ends.map(p=>G.dist(p,toSLD(part[0])))),last=Math.min(...ends.map(p=>G.dist(p,toSLD(part.at(-1)))));if(first<last)part.reverse()}if(c.length){const last=toSLD(c.at(-1));if(G.dist(last,toSLD(part.at(-1)))<G.dist(last,toSLD(part[0])))part.reverse();if(G.dist(last,toSLD(part[0]))>.02)return toast('Selected boundaries have a gap. No connection was added.');part.shift()}c.push(...part)}const poly=$('joinOutput').value==='polygon';if(poly){if(G.dist(toSLD(c[0]),toSLD(c.at(-1)))>.02)return toast('Boundary is not closed. Select the closing line.');c.pop()}const err=G.validate(xy(c),poly);if(err)return toast(err);if(!discardDraft())return;checkpoint();$('method').value=poly?'polygon':'polyline';chooseDestination();draft={method:$('method').value,geometry:poly?'Polygon':'LineString',type:poly?'parcel':'boundary',coords:c,vertexMeta:c.map(()=>({source:'trace'})),snapped:true,layerId:$('drawLayer').value,properties:properties()};mode='draw';render();switchTab('fieldPage');save();hint('Joined boundary ready. Enter details and Save. Source lines retained.')}

 function updateGPS(){if(!lastFix){$('gpsAccuracy').textContent='GPS · no position yet';return}const age=Math.max(0,Math.floor((Date.now()-lastFix.timestamp)/1000));$('gpsAccuracy').textContent='GPS ±'+lastFix.accuracy.toFixed(1)+' m · '+(age>60?'last fix '+Math.floor(age/60)+' min ago':lastFix.recorded?'recorded':'last fix');$('gpsAccuracy').classList.toggle('stale',age>60);$('gpsAccuracy').title='Reported phone position accuracy; it is not parcel boundary accuracy.'}
 function gps(record=false,walk=false){if(!ensure())return;if(!navigator.geolocation)return toast('Location unavailable');if(!window.isSecureContext)return toast('Use the HTTPS GitHub Pages link for GPS');const job=project.id,requestEpoch=epoch,method=$('method').value;const success=p=>guard(()=>{if(!project||project.id!==job||epoch!==requestEpoch||$('method').value!==method)return;const c=[p.coords.longitude,p.coords.latitude],acc=p.coords.accuracy;if(!Number.isFinite(acc)||acc<0)return toast('GPS returned invalid accuracy');lastFix={accuracy:acc,timestamp:p.timestamp||Date.now(),recorded:false};updateGPS();gpsGroup.clearLayers();L.circle(ll(c),{radius:acc,color:'#287dc4',weight:1,fillOpacity:.12,interactive:false}).addTo(gpsGroup);L.circleMarker(ll(c),{radius:7,color:'#fff',fillColor:'#287dc4',weight:3,fillOpacity:1,interactive:false}).addTo(gpsGroup);if(!record){map.panTo(ll(c));return toast('Current position · ±'+acc.toFixed(1)+' m')}
   if(preview||mode.startsWith('split')||mode.startsWith('trace'))return toast('Finish current operation before GPS capture');const max=Math.max(1,+$('maxAccuracy').value||10);if(acc>max){if(walk){$('walkStatus').textContent='Skipped · ±'+acc.toFixed(1)+' m';return}if(!confirm('Phone GPS accuracy ±'+acc.toFixed(1)+' m. Record this approximate position?'))return}if(walk&&draft?.coords.length&&G.dist(toSLD(draft.coords.at(-1)),toSLD(c))<Math.max(.2,+$('walkDistance').value||2))return;const before=draft?.coords.length||0;addPosition(c,{source:'GPS',accuracy:+acc.toFixed(3),timestamp:new Date(p.timestamp).toISOString()});lastFix.recorded=(draft?.coords.length||0)>before;updateGPS();if(walk)$('walkStatus').textContent='Recording · '+(draft?.coords.length||0)+' vertices · ±'+acc.toFixed(1)+' m';else{mode='draw';map.panTo(ll(c));toast('GPS vertex recorded · ±'+acc.toFixed(1)+' m')}});
   const failure=e=>{toast('GPS: '+e.message);$('gpsAccuracy').textContent='GPS unavailable'+(lastFix?' · last ±'+lastFix.accuracy.toFixed(1)+' m':'')},options={enableHighAccuracy:true,maximumAge:0,timeout:20000};if(walk)gpsWatch=navigator.geolocation.watchPosition(success,failure,options);else navigator.geolocation.getCurrentPosition(success,failure,options);
 }
 function openAttributes(){const f=byId(selectedId);if(!f)return toast('Select a feature');for(const[id,k]of Object.entries({editName:'name',editLand:'landName',editClaimant:'claimant',editVillage:'village',editRemark:'remark'}))$(id).value=f.properties[k]||'';$('editLayer').value=f.layerId;$('editLock').checked=!!f.locked;$('editInfo').textContent=meta(f)+' · '+f.coords.length+' vertices';$('featureModal').classList.add('show')}
 function saveAttributes(){const f=byId(selectedId);if(!f)return;if(layer(f.layerId)?.locked)return toast('Unlock source layer first');const dest=layer($('editLayer').value);if(!dest||dest.locked)return toast('Destination layer protected');checkpoint();for(const[id,k]of Object.entries({editName:'name',editLand:'landName',editClaimant:'claimant',editVillage:'village',editRemark:'remark'}))f.properties[k]=$(id).value.trim();f.properties.number=f.properties.name;f.locked=$('editLock').checked;f.layerId=dest.id;close('featureModal');invalidate();render();save()}
 function renderCodes(){const codes=[...new Set([...readJSON(CODES_KEY,['BP','CP','ROAD','STREAM']),...(project?.codes||[])])];$('codeList').innerHTML=codes.map(c=>'<option value="'+esc(c)+'"></option>').join('');if(project)project.codes=codes}
 function newLayer(name,kind='reference',source='survey'){return{id:uid('layer'),name,kind,source,color:source==='survey'?'#287c6b':'#7266bd',visible:true,snap:true,locked:false,export:source==='survey'}}
